import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import { useAuth } from './AuthContext';

function Auth() {
  const navigate = useNavigate();
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [tenant, setTenant] = useState('default');
  const [message, setMessage] = useState('');
  const [profile, setProfile] = useState(null);

  const { token, setToken } = useAuth();

  useEffect(() => {
    if (token) {
      fetchProfile();
    } else {
      setProfile(null);
    }
  }, [token]);

  const fetchProfile = async () => {
    try {
      const res = await axios.get('/api/auth/me');
      setProfile(res.data);
    } catch (err) {
      setMessage(err.response?.data?.error || 'Failed to fetch profile.');
    }
  };

  const register = async () => {
    setMessage(null);
    try {
      const res = await axios.post('/api/auth/register', {
        username,
        password,
        tenant_id: tenant,
      });
      setMessage(res.data.message);
    } catch (err) {
      setMessage(err.response?.data?.error || 'Registration failed.');
    }
  };

  const login = async () => {
    setMessage(null);
    try {
      const res = await axios.post('/api/auth/login', {
        username,
        password,
        tenant_id: tenant,
      });
      setToken(res.data.token);
      setMessage('Login successful. Redirecting...');
      setTimeout(() => navigate('/malware'), 750);
    } catch (err) {
      setMessage(err.response?.data?.error || 'Login failed.');
    }
  };

  const logout = () => {
    setToken(null);
    setProfile(null);
    setMessage('Logged out.');
  };

  return (
    <div>
      <h2>Secure App Demo</h2>
      <div className="row">
        <div className="col-md-6">
          <div className="card mb-3">
            <div className="card-body">
              <h5 className="card-title">Authentication</h5>
              <div className="mb-2">
                <label className="form-label">Username</label>
                <input
                  className="form-control"
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  placeholder="username"
                />
              </div>
              <div className="mb-2">
                <label className="form-label">Tenant ID</label>
                <input
                  className="form-control"
                  value={tenant}
                  onChange={(e) => setTenant(e.target.value)}
                  placeholder="tenant id (e.g. default)"
                />
                <small className="form-text text-muted">Can be a username or email. Used to segment users + scans.</small>
              </div>
              <div className="mb-3">
                <label className="form-label">Password</label>
                <input
                  type="password"
                  className="form-control"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  placeholder="password"
                />
              </div>
              <button className="btn btn-secondary me-2" onClick={register}>
                Register
              </button>
              <button className="btn btn-primary" onClick={login}>
                Login
              </button>
              <button className="btn btn-outline-light ms-2" onClick={logout}>
                Logout
              </button>
              {message && <div className="alert alert-info mt-3">{message}</div>}
            </div>
          </div>
        </div>
        <div className="col-md-6">
          <div className="card mb-3">
            <div className="card-body">
              <h5 className="card-title">Profile</h5>
              {profile ? (
                <div>
                  <p>
                    <strong>Username:</strong> {profile.username}
                  </p>
                  <p>
                    <strong>Role:</strong> {profile.role}
                  </p>
                </div>
              ) : (
                <p className="text-muted">Login to view your profile.</p>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Auth;
